const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Taiwan geometry
  const taiwanGeom = ee.Geometry.Rectangle([120.0, 22.0, 122.5, 25.5]);

  // 2. Define time periods
  const feb_start = '2020-02-10';
  const feb_end = '2020-02-26';
  const apr_start = '2020-04-20';
  const apr_end = '2020-05-13';

  // 3. Acquire S5P NO2 data for February
  const s5p_feb = ee.ImageCollection('COPERNICUS/S5P/OFFL')
    .select('NO2_column_number_density')
    .filterBounds(taiwanGeom)
    .filterDate(feb_start, feb_end)
    .filter(ee.Filter.lt('CLOUD_FRACTION', 0.3));

  const feb_size = s5p_feb.size().getInfo();
  console.log('Feb Images: ' + feb_size);

  if (feb_size === 0) {
    console.log('No data for February 2020.');
    console.log('C1');
    return;
  }

  // 4. Acquire S5P NO2 data for April-May
  const s5p_apr = ee.ImageCollection('COPERNICUS/S5P/OFFL')
    .select('NO2_column_number_density')
    .filterBounds(taiwanGeom)
    .filterDate(apr_start, apr_end)
    .filter(ee.Filter.lt('CLOUD_FRACTION', 0.3));

  const apr_size = s5p_apr.size().getInfo();
  console.log('Apr-May Images: ' + apr_size);

  if (apr_size === 0) {
    console.log('No data for April-May 2020.');
    console.log('C1');
    return;
  }

  // 5. Calculate mean NO2 for February
  const feb_mean_img = s5p_feb.mean();
  const feb_mean = feb_mean_img.reduceRegion(
    ee.Reducer.mean(),
    taiwanGeom,
    1000,
    null,
    null,
    false,
    1e9
  ).get('NO2_column_number_density').getInfo();

  // 6. Calculate mean NO2 for April-May
  const apr_mean_img = s5p_apr.mean();
  const apr_mean = apr_mean_img.reduceRegion(
    ee.Reducer.mean(),
    taiwanGeom,
    1000,
    null,
    null,
    false,
    1e9
  ).get('NO2_column_number_density').getInfo();

  // 7. Check for valid pixels
  const feb_count = feb_mean_img.reduceRegion(
    ee.Reducer.count(),
    taiwanGeom,
    1000,
    null,
    null,
    false,
    1e9
  ).get('NO2_column_number_density').getInfo();

  const apr_count = apr_mean_img.reduceRegion(
    ee.Reducer.count(),
    taiwanGeom,
    1000,
    null,
    null,
    false,
    1e9
  ).get('NO2_column_number_density').getInfo();

  console.log('Feb Valid Pixels: ' + feb_count + ', Mean NO2: ' + (feb_mean ? feb_mean.toFixed(4) : 'null'));
  console.log('Apr Valid Pixels: ' + apr_count + ', Mean NO2: ' + (apr_mean ? apr_mean.toFixed(4) : 'null'));

  // 8. Validation
  if (feb_count === 0 || apr_count === 0) {
    console.log('C2');
    return;
  }

  if (feb_mean === null || apr_mean === null || isNaN(feb_mean) || isNaN(apr_mean)) {
    console.log('C3');
    return;
  }

  // 9. Compare means
  if (apr_mean > feb_mean) {
    console.log('Feb: ' + feb_mean.toFixed(4) + ' µmol/m² → Apr: ' + apr_mean.toFixed(4) + ' µmol/m²');
    console.log('A');
  } else {
    console.log('Feb: ' + feb_mean.toFixed(4) + ' µmol/m² → Apr: ' + apr_mean.toFixed(4) + ' µmol/m²');
    console.log('B');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
